def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    # Solid full-length non-background lines partition the canvas.
    row_seps = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    col_seps = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]
    def bands(size, seps):
        result, start = [], 0
        for x in seps:
            if start < x:
                result.append((start, x))
            start = x + 1
        if start < size:
            result.append((start, size))
        return result
    rb, cb = bands(h, row_seps), bands(w, col_seps)
    if not rb or not cb:
        return [row[:] for row in grid]
    # The panel containing the densest non-background motif is the source.
    scores = [(sum(grid[r][c] != bg for r in range(a,b) for c in range(x,y)), i, j)
              for i,(a,b) in enumerate(rb) for j,(x,y) in enumerate(cb)]
    _, si, sj = max(scores)
    a,b = rb[si]; x,y = cb[sj]
    motif = [grid[r][x:y] for r in range(a,b)]
    out = [row[:] for row in grid]
    for top,bottom in rb:
        for left,right in cb:
            if bottom-top != len(motif) or right-left != len(motif[0]):
                continue
            for r in range(top,bottom):
                for c in range(left,right):
                    out[r][c] = motif[r-top][c-left]
    return out
